     1→import type { FogMask, FogStroke } from "../types";
     2→
     3→export function createMask(width: number, height: number): FogMask {
     4→  return { width, height, data: new Uint8Array(width * height).fill(255) };
     5→}
     6→
     7→export function createRevealedMask(width: number, height: number): FogMask {
     8→  return { width, height, data: new Uint8Array(width * height) };
     9→}
    10→
    11→export function applyStroke(mask: FogMask, stroke: FogStroke): void {
    12→  const { x, y, radius, mode } = stroke;
    13→  const value = mode === "reveal" ? 0 : 255;
    14→  const r2 = radius * radius;
    15→  const x0 = Math.max(0, Math.floor(x - radius));
    16→  const x1 = Math.min(mask.width - 1, Math.ceil(x + radius));
    17→  const y0 = Math.max(0, Math.floor(y - radius));
    18→  const y1 = Math.min(mask.height - 1, Math.ceil(y + radius));
    19→  for (let py = y0; py <= y1; py++) {
    20→    for (let px = x0; px <= x1; px++) {
    21→      const dx = px - x;
    22→      const dy = py - y;
    23→      if (dx * dx + dy * dy <= r2) {
    24→        mask.data[py * mask.width + px] = value;
    25→      }
    26→    }
    27→  }
    28→}
    29→
    30→export function applyStrokes(mask: FogMask, strokes: FogStroke[]): void {
    31→  for (const stroke of strokes) {
    32→    applyStroke(mask, stroke);
    33→  }
    34→}
    35→
    36→export function isRevealed(mask: FogMask, x: number, y: number): boolean {
    37→  if (x < 0 || x >= mask.width || y < 0 || y >= mask.height) return false;
    38→  return mask.data[y * mask.width + x] === 0;
    39→}
    40→
    41→export function getRevealedPercentage(mask: FogMask): number {
    42→  let revealed = 0;
    43→  for (let i = 0; i < mask.data.length; i++) {
    44→    if (mask.data[i] === 0) revealed++;
    45→  }
    46→  return mask.data.length === 0 ? 0 : revealed / mask.data.length;
    47→}
    48→

