*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, sans-serif;
  background: #0d0d1a;
  color: #e0e0e0;
  height: 100vh;
  overflow: hidden;
}

/* ── Home page ── */
body.home {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
}
.home-main { width: 100%; max-width: 480px; padding: 2rem; }
.home-main h1 { font-size: 2rem; margin-bottom: 1.5rem; text-align: center; }
.card {
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1rem;
}
.card h2 { margin-bottom: 1rem; font-size: 1.1rem; }
.card label { display: flex; flex-direction: column; gap: 4px; margin-bottom: 0.75rem; font-size: 0.85rem; color: #aaa; }
.card input[type=text],
.card input[type=password],
.card input[type=color] {
  padding: 0.4rem 0.6rem;
  background: #0d0d1a;
  border: 1px solid #333;
  border-radius: 4px;
  color: #e0e0e0;
  font-size: 1rem;
}
.card input[type=color] { height: 2rem; cursor: pointer; }
.card button {
  width: 100%;
  padding: 0.5rem;
  background: #4a4aff;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}
.card button:hover { background: #3333cc; }
.error { color: #e74c3c; margin-top: 0.5rem; font-size: 0.85rem; }

/* ── GM page layout ── */
body.gm {
  display: grid;
  grid-template-rows: 44px 1fr;
  grid-template-columns: 180px 1fr 180px;
  grid-template-areas:
    "topbar topbar topbar"
    "left   canvas right";
}

#topbar {
  grid-area: topbar;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0 1rem;
  background: #1a1a2e;
  border-bottom: 1px solid #2a2a4a;
  overflow: hidden;
}
#adventure-name { font-weight: 600; white-space: nowrap; }
.invite-row { display: flex; align-items: center; gap: 0.5rem; flex: 1; min-width: 0; }
.invite-link-text { font-size: 0.75rem; color: #888; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; }
.invite-row button { flex-shrink: 0; padding: 0.2rem 0.5rem; background: #2a2a4a; border: 1px solid #444; border-radius: 4px; color: #ccc; cursor: pointer; font-size: 0.8rem; }

#sidebar-left {
  grid-area: left;
  background: #111122;
  border-right: 1px solid #2a2a4a;
  padding: 1rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  overflow-y: auto;
}
.control-group label { font-size: 0.8rem; color: #aaa; display: block; margin-bottom: 0.4rem; }
.control-group input[type=range] { width: 100%; accent-color: #4a4aff; }
.mode-buttons { display: flex; gap: 0.5rem; }
.mode-buttons button {
  flex: 1;
  padding: 0.35rem 0;
  background: #1a1a2e;
  border: 1px solid #333;
  border-radius: 4px;
  color: #aaa;
  cursor: pointer;
  font-size: 0.85rem;
}
.mode-buttons button.active { background: #4a4aff; border-color: #4a4aff; color: #fff; }
#status-bar { font-size: 0.75rem; color: #555; }

#canvas-area {
  grid-area: canvas;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  overflow: hidden;
  position: relative;
}

#sidebar-right {
  grid-area: right;
  background: #111122;
  border-left: 1px solid #2a2a4a;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
#gallery {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.gallery-item {
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  overflow: hidden;
  background: #0d0d1a;
}
.gallery-item:hover { border-color: #4a4aff88; }
.gallery-item.active { border-color: #4a4aff; }
.gallery-item img { width: 100%; height: 80px; object-fit: cover; display: block; }
.upload-row { padding: 0.5rem; border-top: 1px solid #2a2a4a; }
.upload-btn {
  display: block;
  text-align: center;
  padding: 0.4rem;
  background: #1a1a2e;
  border: 1px dashed #444;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.85rem;
  color: #aaa;
}
.upload-btn:hover { border-color: #4a4aff; color: #ccc; }

/* ── Player page ── */
body.player {
  display: flex;
  align-items: center;
  justify-content: center;
}
#player-root { text-align: center; color: #888; }

export interface Adventure {
  id: string;
  name: string;
  player_link: string;
  active_image_id: string | null;
  gm_password: string;
}

export interface ImageRecord {
  id: string;
  adventure_id: string;
  filename: string;
  original_name: string;
  width: number;
  height: number;
  sort_order: number;
}

function gmHeaders(password: string): HeadersInit {
  return { 'X-GM-Password': password };
}

async function checkOk(res: Response): Promise<Response> {
  if (!res.ok) {
    const text = await res.text().catch(() => res.statusText);
    throw new Error(`HTTP ${res.status}: ${text}`);
  }
  return res;
}

export async function createAdventure(name: string, password: string): Promise<Adventure> {
  const res = await fetch('/api/adventures', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name, gmPassword: password }),
  });
  return (await checkOk(res)).json();
}

export async function getAdventure(adventureId: string, password: string): Promise<Adventure> {
  const res = await fetch(`/api/adventures/${adventureId}`, {
    headers: gmHeaders(password),
  });
  return (await checkOk(res)).json();
}

export async function uploadImage(adventureId: string, password: string, file: File): Promise<ImageRecord> {
  const form = new FormData();
  form.append('file', file);
  const res = await fetch(`/api/adventures/${adventureId}/images`, {
    method: 'POST',
    headers: gmHeaders(password),
    body: form,
  });
  return (await checkOk(res)).json();
}

export async function listImages(adventureId: string, password: string): Promise<ImageRecord[]> {
  const res = await fetch(`/api/adventures/${adventureId}/images`, {
    headers: gmHeaders(password),
  });
  return (await checkOk(res)).json();
}

export async function deleteImage(adventureId: string, password: string, imageId: string): Promise<void> {
  const res = await fetch(`/api/adventures/${adventureId}/images/${imageId}`, {
    method: 'DELETE',
    headers: gmHeaders(password),
  });
  await checkOk(res);
}

export async function switchActiveImage(adventureId: string, password: string, imageId: string): Promise<void> {
  const res = await fetch(`/api/adventures/${adventureId}/active-image`, {
    method: 'PUT',
    headers: { ...gmHeaders(password), 'Content-Type': 'application/json' },
    body: JSON.stringify({ imageId }),
  });
  await checkOk(res);
}

export type MessageHandler = (msg: Record<string, unknown>) => void;

export interface WebSocketClient {
  send(msg: Record<string, unknown>): void;
  on(type: string, handler: MessageHandler): void;
  close(): void;
}

export function connectGM(adventureId: string, password: string): WebSocketClient {
  const handlers = new Map<string, MessageHandler[]>();
  let ws: WebSocket | null = null;
  let closed = false;
  let backoff = 1000;

  function emit(type: string, msg: Record<string, unknown>) {
    for (const h of handlers.get(type) ?? []) {
      try { h(msg); } catch (e) { console.error('ws handler error', e); }
    }
  }

  function buildUrl(): string {
    const u = new URL('/ws', window.location.href);
    u.protocol = u.protocol === 'https:' ? 'wss:' : 'ws:';
    u.searchParams.set('adventureId', adventureId);
    u.searchParams.set('role', 'gm');
    u.searchParams.set('password', password);
    return u.toString();
  }

  function connect() {
    if (closed) return;
    try {
      ws = new WebSocket(buildUrl());
    } catch {
      scheduleReconnect();
      return;
    }

    ws.onopen = () => {
      backoff = 1000;
      emit('connect', {});
    };

    ws.onmessage = (ev) => {
      try {
        const msg = JSON.parse(ev.data as string) as Record<string, unknown>;
        if (typeof msg?.type === 'string') emit(msg.type, msg);
      } catch {}
    };

    ws.onerror = () => { ws?.close(); };

    ws.onclose = () => {
      ws = null;
      if (closed) return;
      emit('disconnect', {});
      scheduleReconnect();
    };
  }

  function scheduleReconnect() {
    setTimeout(() => { backoff = Math.min(backoff * 2, 30000); connect(); }, backoff);
  }

  connect();

  return {
    send(msg: Record<string, unknown>) {
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(msg));
      }
    },
    on(type: string, handler: MessageHandler) {
      if (!handlers.has(type)) handlers.set(type, []);
      handlers.get(type)!.push(handler);
    },
    close() {
      closed = true;
      ws?.close();
    },
  };
}

export interface FogStroke {
  x: number;
  y: number;
  radius: number;
  mode: 'reveal' | 'fog';
}

export interface CanvasController {
  loadImage(url: string): Promise<void>;
  applyFogMask(base64: string): Promise<void>;
  applyStroke(stroke: FogStroke): void;
  drawBrushPreview(imgX: number, imgY: number, radius: number): void;
  clearBrushPreview(): void;
  screenToImage(clientX: number, clientY: number): { x: number; y: number };
  getEventTarget(): HTMLCanvasElement;
  clear(): void;
}

const FOG_ALPHA = 0.85;
const FOG_FILL = `rgba(0,0,0,${FOG_ALPHA})`;

async function decompress(data: Uint8Array): Promise<Uint8Array> {
  // Try zlib (deflate with header) first, then raw deflate
  for (const fmt of ['deflate', 'deflate-raw'] as CompressionFormat[]) {
    try {
      const ds = new DecompressionStream(fmt);
      const writer = ds.writable.getWriter();
      const reader = ds.readable.getReader();
      // Clone data to avoid detached buffer on retry
      writer.write(data.slice());
      writer.close();
      const chunks: Uint8Array[] = [];
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
      }
      const total = chunks.reduce((n, c) => n + c.length, 0);
      const out = new Uint8Array(total);
      let off = 0;
      for (const c of chunks) { out.set(c, off); off += c.length; }
      return out;
    } catch {
      // try next format
    }
  }
  throw new Error('Failed to decompress fog mask');
}

export function initCanvas(container: HTMLElement): CanvasController {
  const wrapper = document.createElement('div');
  wrapper.style.cssText = 'position:relative;flex-shrink:0;';
  container.appendChild(wrapper);

  function makeCanvas(): HTMLCanvasElement {
    const c = document.createElement('canvas');
    c.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';
    wrapper.appendChild(c);
    return c;
  }

  const mapCanvas = makeCanvas();
  const fogCanvas = makeCanvas();
  const previewCanvas = makeCanvas();
  previewCanvas.style.pointerEvents = 'none';

  const mapCtx = mapCanvas.getContext('2d')!;
  const fogCtx = fogCanvas.getContext('2d')!;
  const previewCtx = previewCanvas.getContext('2d')!;

  let imgW = 0;
  let imgH = 0;

  function sizeAll(w: number, h: number) {
    imgW = w;
    imgH = h;
    for (const c of [mapCanvas, fogCanvas, previewCanvas]) {
      c.width = w;
      c.height = h;
    }
    const cw = container.clientWidth || 800;
    const ch = container.clientHeight || 600;
    const scale = Math.min(cw / w, ch / h);
    wrapper.style.width = `${Math.round(w * scale)}px`;
    wrapper.style.height = `${Math.round(h * scale)}px`;
  }

  function fillFog() {
    fogCtx.save();
    fogCtx.globalCompositeOperation = 'source-over';
    fogCtx.fillStyle = FOG_FILL;
    fogCtx.fillRect(0, 0, imgW, imgH);
    fogCtx.restore();
  }

  return {
    async loadImage(url: string) {
      const img = new Image();
      await new Promise<void>((res, rej) => {
        img.onload = () => res();
        img.onerror = () => rej(new Error(`Failed to load image: ${url}`));
        img.src = url;
      });
      sizeAll(img.naturalWidth, img.naturalHeight);
      mapCtx.clearRect(0, 0, imgW, imgH);
      mapCtx.drawImage(img, 0, 0);
      fogCtx.clearRect(0, 0, imgW, imgH);
      fillFog();
      previewCtx.clearRect(0, 0, imgW, imgH);
    },

    async applyFogMask(base64: string) {
      const bin = atob(base64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      const view = new DataView(bytes.buffer);
      const w = view.getUint32(0, false);
      const h = view.getUint32(4, false);
      const pixels = await decompress(bytes.slice(8));
      if (imgW !== w || imgH !== h) sizeAll(w, h);
      const id = fogCtx.createImageData(w, h);
      for (let i = 0; i < pixels.length; i++) {
        const v = pixels[i];
        id.data[i * 4 + 0] = 0;
        id.data[i * 4 + 1] = 0;
        id.data[i * 4 + 2] = 0;
        id.data[i * 4 + 3] = Math.round(v * FOG_ALPHA);
      }
      fogCtx.putImageData(id, 0, 0);
    },

    applyStroke(stroke: FogStroke) {
      if (imgW === 0) return;
      fogCtx.save();
      fogCtx.beginPath();
      fogCtx.arc(stroke.x, stroke.y, stroke.radius, 0, Math.PI * 2);
      if (stroke.mode === 'reveal') {
        fogCtx.globalCompositeOperation = 'destination-out';
        fogCtx.fillStyle = 'rgba(0,0,0,1)';
      } else {
        fogCtx.globalCompositeOperation = 'source-over';
        fogCtx.fillStyle = FOG_FILL;
      }
      fogCtx.fill();
      fogCtx.restore();
    },

    drawBrushPreview(imgX: number, imgY: number, radius: number) {
      if (imgW === 0) return;
      previewCtx.clearRect(0, 0, imgW, imgH);
      previewCtx.save();
      previewCtx.strokeStyle = 'rgba(255,255,255,0.7)';
      previewCtx.lineWidth = Math.max(1, 2 * (imgW / (wrapper.clientWidth || imgW)));
      previewCtx.beginPath();
      previewCtx.arc(imgX, imgY, radius, 0, Math.PI * 2);
      previewCtx.stroke();
      previewCtx.restore();
    },

    clearBrushPreview() {
      if (imgW > 0) previewCtx.clearRect(0, 0, imgW, imgH);
    },

    screenToImage(clientX: number, clientY: number) {
      const rect = fogCanvas.getBoundingClientRect();
      return {
        x: (clientX - rect.left) * (imgW / (rect.width || 1)),
        y: (clientY - rect.top) * (imgH / (rect.height || 1)),
      };
    },

    getEventTarget() { return fogCanvas; },

    clear() {
      mapCtx.clearRect(0, 0, imgW, imgH);
      fogCtx.clearRect(0, 0, imgW, imgH);
      previewCtx.clearRect(0, 0, imgW, imgH);
